    this.tail = null
    this.length = 0
    if (value !== undefined) {
      const newNode = new Node(value)
      this.head = newNode
      this.tail = this.head
      this.length = 1
    }
  }

  push(value) {
    // 1. make a new node with the value
    // 2. if the list is empty: head and tail both point to the new node
    // 3. otherwise: the last node's next points to the new node,
    //    then tail moves to the new node
    // 4. add 1 to length
    // 5. return the list (this)
  }

  // our helper: the values from head to tail, as an array
  toArray() {
    const values = []
    let temp = this.head
    while (temp !== null) {
      values.push(temp.value)
      temp = temp.next
    }
    return values
  }
}

